<div class="module-intro"><div><span class="eyebrow">PLANEJAMENTO DE EQUIPES</span><h2>Escalas de serviço</h2><p>Calendário, turnos e alocação de servidores.</p></div><?php if($canCreate): ?><button class="btn primary" data-toggle-target="shift-form">＋ Nova escala</button><?php endif; ?></div>
<form method="get" class="filter-bar"><label>De<input type="date" name="from" value="<?= e($filters['from']) ?>"></label><label>Até<input type="date" name="to" value="<?= e($filters['to']) ?>"></label><button class="btn subtle">Consultar período</button></form>
<?php if($canCreate||$editShift): ?><form id="shift-form" class="panel form-panel <?= $editShift?'':'hidden' ?>" method="post" action="<?= e($baseUrl) ?>/escala/salvar"><input type="hidden" name="_csrf" value="<?= e($csrf) ?>"><input type="hidden" name="id" value="<?= (int)($editShift['id']??0) ?>"><div class="section-heading"><div><h3><?= $editShift?'Editar escala':'Cadastrar escala' ?></h3><p>Conflitos de horário serão verificados antes de salvar.</p></div></div><div class="form-grid"><label>Identificação *<input name="title" required value="<?= e($editShift['title']??'') ?>"></label><label>Tipo de serviço *<input name="service_type" required value="<?= e($editShift['service_type']??'') ?>"></label><label>Data *<input type="date" name="service_date" value="<?= date('Y-m-d') ? value="<?= e($editShift['service_date']??'<?= date('Y-m-d') ?>') ?>">" required></label><label>Local *<input name="location" required value="<?= e($editShift['location']??'') ?>"></label><label>Início *<input type="time" name="start_time" required value="<?= e($editShift['start_time']??'') ?>"></label><label>Término *<input type="time" name="end_time" required value="<?= e($editShift['end_time']??'') ?>"></label><label>Equipe<input name="team_name" value="<?= e($editShift['team_name']??'') ?>"></label><label class="full">Observações<textarea name="notes" rows="2"><?= e($editShift['notes']??'') ?></textarea></label></div><fieldset><legend>Servidores escalados *</legend><div class="staff-checks"><?php foreach($staff as $s): ?><label><input type="checkbox" name="members[]" value="<?= (int)$s['id'] ?>" <?= in_array((int)$s['id'],$editShift['members']??[],true)?'checked':'' ?>> <?= e($s['name']) ?></label><?php endforeach; ?></div></fieldset><div class="form-actions"><button class="btn primary"><?= $editShift?'Atualizar escala':'Salvar rascunho' ?></button><button type="button" class="btn subtle" data-toggle-target="shift-form">Cancelar</button></div></form><?php endif; ?>
<section class="panel"><div class="section-heading"><div><h3>Agenda de escalas</h3><p>Registros entre <?= date('d/m/Y',strtotime($filters['from'])) ?> e <?= date('d/m/Y',strtotime($filters['to'])) ?></p></div></div><?php if(!$shifts): ?><div class="table-empty">Nenhuma escala encontrada no período.</div><?php else: ?><div class="table-wrap"><table><thead><tr><th>Data</th><th>Serviço</th><th>Horário</th><th>Local</th><th>Equipe</th><th>Servidores</th><th>Status</th><th>Ações</th></tr></thead><tbody><?php foreach($shifts as $s): ?><tr><td><?= date('d/m/Y',strtotime($s['service_date'])) ?></td><td><b><?= e($s['title']) ?></b><small><?= e($s['service_type']) ?></small></td><td><?= e(substr($s['start_time'],0,5)) ?>–<?= e(substr($s['end_time'],0,5)) ?></td><td><?= e($s['location']) ?></td><td><?= e($s['team_name']??'—') ?></td><td><?= (int)$s['member_count'] ?></td><td><span class="state-pill"><?= e($s['status']) ?></span></td><td class="actions-cell"><a class="text-link" href="<?= e($baseUrl) ?>/escala/<?= (int)$s['id'] ?>">Detalhes</a><?php if($s['status']==='Rascunho'&&$this->allowed('escalas.publish')): ?><form method="post" action="<?= e($baseUrl) ?>/escala/acao"><input type="hidden" name="_csrf" value="<?= e($csrf) ?>"><input type="hidden" name="id" value="<?= (int)$s['id'] ?>"><input type="hidden" name="action" value="publish"><button class="btn tiny">Publicar</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>